#!/usr/bin/env ruby
require 'json';require 'digest';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);package=JSON.parse(File.read(File.join(client,'package.json')));locks=Dir.glob(File.join(client,'{pnpm-lock.yaml,package-lock.json,yarn.lock,npm-shrinkwrap.json}')).select{|p|File.file?(p)};checks={singleLock:locks.map{|p|File.basename(p)}==['pnpm-lock.yaml'],packageManager:package['packageManager']=='pnpm@11.19.0',nodePinned:package.dig('engines','node')=='20.10.0',pnpmPinned:package.dig('engines','pnpm')=='11.19.0',lockVersion:File.read(locks.first).include?("lockfileVersion: '9.0'")};report={schemaVersion:1,locks:locks.map{|p|{path:p.delete_prefix(client+'/'),sha256:Digest::SHA256.file(p).hexdigest}},packageManager:package['packageManager'],engines:package['engines'],checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/chyg02-package-manager.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG02 failed: #{checks}" unless report[:passed];puts 'CHYG02 PASS: pnpm, Node and lock source uniquely pinned'
